package org.jackhuang.hmcl.script;

import org.jetbrains.annotations.NotNullByDefault;
import org.junit.jupiter.api.Test;
import java.util.Objects;
import static org.junit.jupiter.api.Assertions.*;

/// Exercises editor behavior from the user's resulting text and selection, independent of JavaFX skins.
@NotNullByDefault
public final class ScriptEditingTest {
    /// Applies an atomic replacement to a source string.
    private static String apply(String text, ScriptEditing.Edit edit) { return text.substring(0, edit.start()) + edit.replacement() + text.substring(edit.end()); }
    /// Open delimiters generate a matching close and leave the caret inside.
    @Test public void pairsAndSelections() { var pair = Objects.requireNonNull(ScriptEditing.typed("", 0, 0, '(')); assertEquals("()", apply("", pair)); assertEquals(1, pair.caret()); var wrap = Objects.requireNonNull(ScriptEditing.typed("value", 0, 5, '{')); assertEquals("{value}", apply("value", wrap)); assertEquals(1, wrap.anchor()); assertEquals(6, wrap.caret()); }
    /// Closing an autogenerated delimiter moves the caret rather than inserting a duplicate.
    @Test public void closingDelimiter() { var skip = Objects.requireNonNull(ScriptEditing.typed("()", 1, 1, ')')); assertEquals("()", apply("()", skip)); assertEquals(2, skip.caret()); }
    /// Automatic pairing is suppressed in comments and ordinary string contents, including escaped quotes.
    @Test public void stringsCommentsAndEscapes() { assertNull(ScriptEditing.typed("// note ", 8, 8, '(')); assertNull(ScriptEditing.typed("\"abc", 4, 4, '(')); assertNull(ScriptEditing.typed("\"a\\\"", 3, 3, '"')); assertNull(ScriptEditing.typed("\")\"", 1, 1, ')')); }
    /// A single backspace removes both halves of an empty generated pair.
    @Test public void deletePair() { assertEquals("", apply("{}", Objects.requireNonNull(ScriptEditing.backspace("{}", 1, 1)))); assertNull(ScriptEditing.backspace("{x}", 2, 2)); }
    /// Enter between braces creates an indented body and a separately aligned closing brace.
    @Test public void blockIndentation() { var edit = ScriptEditing.newline("if (true) {}", 11, 11); assertEquals("if (true) {\n    \n}", apply("if (true) {}", edit)); assertEquals(16, edit.caret()); }
    /// Existing indentation survives Enter, including an empty first line edge case.
    @Test public void inheritedIndentation() { assertEquals("    print(1);\n    ", apply("    print(1);", ScriptEditing.newline("    print(1);", 13, 13))); assertEquals("\n\na", apply("\na", ScriptEditing.newline("\na", 0, 0))); }
    /// Tab and Shift+Tab operate on complete selected lines without touching the following unselected line.
    @Test public void multilineIndentation() { String text = "a\nb\nc"; var edit = ScriptEditing.indent(text, 0, 4, false); assertEquals("    a\n    b\nc", apply(text, edit)); String changed = apply(text, edit); assertEquals(text, apply(changed, ScriptEditing.indent(changed, edit.anchor(), edit.caret(), true))); }
    /// Comment toggling preserves indentation and is reversible for a multiline selection.
    @Test public void comments() { String text = "    print(1);\nprint(2);"; var edit = ScriptEditing.comment(text, 0, text.length()); String changed = apply(text, edit); assertEquals("    // print(1);\n// print(2);", changed); assertEquals(text, apply(changed, ScriptEditing.comment(changed, edit.anchor(), edit.caret()))); }
    /// Duplicate-line behavior works at EOF without requiring an existing trailing newline.
    @Test public void duplicateLines() { assertEquals("a\nb\nb", apply("a\nb", ScriptEditing.duplicate("a\nb", 2, 2))); }
    /// Moving selected lines preserves their order and handles an empty first line.
    @Test public void moveLines() { assertEquals("b\na\nc", apply("a\nb\nc", Objects.requireNonNull(ScriptEditing.move("a\nb\nc", 0, 0, true)))); assertEquals("b\na\nc", apply("a\nb\nc", Objects.requireNonNull(ScriptEditing.move("a\nb\nc", 2, 2, false)))); assertEquals("a\n", apply("\na", Objects.requireNonNull(ScriptEditing.move("\na", 1, 1, false)))); assertNull(ScriptEditing.move("a", 0, 0, false)); }
}
